-- Run in a new empty user database. Does not drop or replace existing tables.

SET XACT_ABORT ON;

BEGIN TRANSACTION;

CREATE TABLE dbo.[games] ([game_id] NVARCHAR(128) PRIMARY KEY,
[game_order] INT NOT NULL,
[game_timestamp] DATETIME2(0) NOT NULL,
[game_date] DATE NOT NULL,
[game_on_date] INT NOT NULL,
[home] INT NOT NULL,
[opponent] NVARCHAR(128) NOT NULL,
[result] NVARCHAR(128) NOT NULL,
[win] INT NOT NULL,
[runs_for] INT NOT NULL,
[runs_against] INT NOT NULL,
[run_differential] INT NOT NULL,
[split] NVARCHAR(128) NOT NULL,
[pitch_count] INT NOT NULL,
[pa_count] INT NOT NULL,
[routine_n] INT NOT NULL,
[routine_mean_secs] FLOAT NOT NULL,
[routine_sd_secs] FLOAT NOT NULL,
[routine_cv] FLOAT NOT NULL,
[tic_n] INT NOT NULL,
[tics_mean] FLOAT NOT NULL,
[disruption_count] INT NOT NULL,
[disruption_rate] FLOAT NOT NULL,
[risp_rate] FLOAT NOT NULL,
[logged_offensive_innings] INT NOT NULL,
[prior_5_win_rate] FLOAT,
[window_win_streak_before] INT NOT NULL,
[disruption_coverage] NVARCHAR(128) NOT NULL);


CREATE TABLE dbo.[batters] ([batter_id] NVARCHAR(128) PRIMARY KEY,
[batter_name] NVARCHAR(128) NOT NULL);


CREATE TABLE dbo.[plate_appearances] ([pa_id] NVARCHAR(128) PRIMARY KEY,
[game_id] NVARCHAR(128) NOT NULL,
[batter_id] NVARCHAR(128) NOT NULL,
[inning] INT NOT NULL,
[first_source_row] INT NOT NULL,
[last_source_row] INT NOT NULL,
[pitch_count] INT NOT NULL,
[pa_result] NVARCHAR(128) NOT NULL,
[pa_group] NVARCHAR(128) NOT NULL,
[strikeout] INT NOT NULL,
[hit_any] INT NOT NULL,
[walk] INT NOT NULL,
[hbp] INT NOT NULL,
[pa_sequence_valid] INT NOT NULL,
[outcome_inferred] INT NOT NULL,
[outcome_comment_corrected] INT NOT NULL,
[risp_start] INT NOT NULL,
[disrupted_first_pitch] INT NOT NULL,
[disrupted_any] INT NOT NULL,
[disrupted_pitches] INT NOT NULL,
[routine_n] INT NOT NULL,
[routine_mean_secs] FLOAT,
[routine_sd_secs] FLOAT,
[tic_n] INT NOT NULL,
[tics_mean] FLOAT,
[outcome_model_eligible] INT NOT NULL,
FOREIGN KEY ([game_id]) REFERENCES dbo.[games]([game_id]),
FOREIGN KEY ([batter_id]) REFERENCES dbo.[batters]([batter_id]));









CREATE TABLE dbo.[pitches] ([pitch_id] NVARCHAR(128) PRIMARY KEY,
[pa_id] NVARCHAR(128) NOT NULL,
[source_row] INT NOT NULL,
[pitch_number_pa] INT NOT NULL,
[pre_balls] INT,
[pre_strikes] INT,
[runner_on_first] INT NOT NULL,
[runner_on_second] INT NOT NULL,
[runner_on_third] INT NOT NULL,
[risp] INT NOT NULL,
[runners_on] INT NOT NULL,
[pitcher_disruption] INT NOT NULL,
[routine_time_secs] FLOAT,
[glove_straps] INT,
[helmet_touches] INT,
[plate_taps] INT,
[total_tics] INT,
[pitch_result] NVARCHAR(128) NOT NULL,
[is_terminal] INT NOT NULL,
[routine_over_60_secs] INT NOT NULL,
[routine_source] NVARCHAR(128) NOT NULL,
[tics_source] NVARCHAR(128) NOT NULL,
[disruption_source] NVARCHAR(128) NOT NULL,
[routine_model_eligible] INT NOT NULL,
[tics_model_eligible] INT NOT NULL,
[prediction_eligible] INT NOT NULL,
FOREIGN KEY ([pa_id]) REFERENCES dbo.[plate_appearances]([pa_id]));






























CREATE INDEX ix_plate_appearances_game_id ON dbo.[plate_appearances]([game_id]);

CREATE INDEX ix_plate_appearances_batter_id ON dbo.[plate_appearances]([batter_id]);

CREATE INDEX ix_pitches_pa_id ON dbo.[pitches]([pa_id]);

COMMIT TRANSACTION;

GO

CREATE VIEW dbo.[project1_pitches] AS SELECT p.pitch_id,a.pa_id,a.game_id,a.batter_id,b.batter_name,g.game_date,g.split,g.home,g.opponent,a.inning,p.pitch_number_pa,p.pre_balls,p.pre_strikes,p.risp,p.runners_on,p.pitcher_disruption,p.routine_time_secs,p.total_tics,p.routine_source,p.routine_model_eligible,p.tics_model_eligible,a.pa_sequence_valid FROM dbo.[pitches] p JOIN dbo.[plate_appearances] a ON a.pa_id=p.pa_id JOIN dbo.[games] g ON g.game_id=a.game_id JOIN dbo.[batters] b ON b.batter_id=a.batter_id WHERE p.routine_model_eligible=1 OR p.tics_model_eligible=1;
GO

CREATE VIEW dbo.[project2_pas] AS SELECT a.pa_id,a.game_id,a.batter_id,b.batter_name,g.game_date,g.split,g.home,g.opponent,a.inning,a.risp_start,a.disrupted_first_pitch,a.disrupted_any,a.disrupted_pitches,a.pitch_count,a.strikeout,a.pa_result,a.outcome_comment_corrected FROM dbo.[plate_appearances] a JOIN dbo.[games] g ON g.game_id=a.game_id JOIN dbo.[batters] b ON b.batter_id=a.batter_id WHERE a.outcome_model_eligible=1;
GO

CREATE VIEW dbo.[project3_snapshots] AS SELECT p.pitch_id,a.pa_id,a.game_id,g.game_date,g.split,p.pitch_number_pa,p.pre_balls,p.pre_strikes,p.routine_time_secs,p.total_tics,a.pa_group AS target_pa_group,a.strikeout AS target_strikeout FROM dbo.[pitches] p JOIN dbo.[plate_appearances] a ON a.pa_id=p.pa_id JOIN dbo.[games] g ON g.game_id=a.game_id WHERE p.prediction_eligible=1;
GO

CREATE VIEW dbo.[project4_games] AS SELECT * FROM dbo.[games];
GO